for ref in final['source_references']:
 assert all(i in coverage[ref['path']] for a,b in ref['lines'] for i in range(a,b+1))
assert final['observations'][1]['conceptual_geometry'].startswith('With a positive pass budget')
assert 'has not yet received a separate semantic review' in final['review_qualification']
assert 'prepare at 164–176' in (P/'initial/INITIAL-REVIEW.json').read_text()
changed=sorted(k for k in set(orig)|set(final) if orig.get(k)!=final.get(k));assert changed==['central_display_evidence','observations','review_qualification','source_references']
